CREATE TABLE guest_session (id BINARY(16) PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE artist (id BINARY(16) PRIMARY KEY, name VARCHAR(255) NOT NULL, sort_name VARCHAR(255) NOT NULL, UNIQUE KEY uk_artist_sort_name (sort_name));
CREATE TABLE recording (id BINARY(16) PRIMARY KEY, artist_id BINARY(16) NOT NULL, title VARCHAR(255) NOT NULL, album_title VARCHAR(255), version_label VARCHAR(128), seed_rank INT NOT NULL, CONSTRAINT fk_recording_artist FOREIGN KEY (artist_id) REFERENCES artist(id), UNIQUE KEY uk_recording_artist_title (artist_id,title));
CREATE TABLE tournament (id BINARY(16) PRIMARY KEY, guest_session_id BINARY(16) NOT NULL, artist_id BINARY(16), candidate_source VARCHAR(32) NOT NULL, exploration_brief TEXT, agent_guidance_requested BOOLEAN NOT NULL DEFAULT FALSE, size INT NOT NULL, status VARCHAR(32) NOT NULL, bracket_seed BIGINT NOT NULL, winner_entry_id BINARY(16), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), started_at TIMESTAMP(3), completed_at TIMESTAMP(3), deleted_at TIMESTAMP(3), CONSTRAINT chk_tournament_size CHECK (size IN (16,32)), CONSTRAINT fk_tournament_guest FOREIGN KEY (guest_session_id) REFERENCES guest_session(id), CONSTRAINT fk_tournament_artist FOREIGN KEY (artist_id) REFERENCES artist(id));
CREATE TABLE tournament_entry (id BINARY(16) PRIMARY KEY, tournament_id BINARY(16) NOT NULL, recording_id BINARY(16) NOT NULL, title_snapshot VARCHAR(255) NOT NULL, artist_name_snapshot VARCHAR(255) NOT NULL, album_title_snapshot VARCHAR(255), version_label_snapshot VARCHAR(128), CONSTRAINT fk_entry_tournament FOREIGN KEY (tournament_id) REFERENCES tournament(id), CONSTRAINT fk_entry_recording FOREIGN KEY (recording_id) REFERENCES recording(id), UNIQUE KEY uk_entry_recording (tournament_id,recording_id));
CREATE TABLE tournament_match (id BINARY(16) PRIMARY KEY, tournament_id BINARY(16) NOT NULL, round_number INT NOT NULL, match_index INT NOT NULL, left_entry_id BINARY(16), right_entry_id BINARY(16), winner_entry_id BINARY(16), next_match_id BINARY(16), next_slot VARCHAR(8), status VARCHAR(32) NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT fk_match_tournament FOREIGN KEY (tournament_id) REFERENCES tournament(id), UNIQUE KEY uk_match_position (tournament_id,round_number,match_index));
CREATE TABLE vote (id BINARY(16) PRIMARY KEY, match_id BINARY(16) NOT NULL, selected_entry_id BINARY(16) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT fk_vote_match FOREIGN KEY (match_id) REFERENCES tournament_match(id), UNIQUE KEY uk_vote_match (match_id), UNIQUE KEY uk_vote_key (idempotency_key));
